(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
 /* Oberflaeche rendert aus Schluesseln der Datenbank. */
 ["de","en","fr"].forEach(function(l){
   M.I18N[l]=Object.assign(M.I18N[l]||{},window.MNEMIKA_UI_DB[l]||{});});
 var PT=window.MNEMIKA_PROGRAM_TEXT_DB, CT=window.MNEMIKA_CONFIG_TEXT_DB;
 M.programLabel=function(p){var t=PT[p&&p.id];var l=M.locale();
   return (t&&t.labels&&t.labels[l])||(t&&t.labels&&t.labels.de)||(p&&p.label)||"";};
 M.programDescription=function(p){var t=PT[p&&p.id];var l=M.locale();
   return (t&&t.descriptions&&t.descriptions[l])||(t&&t.descriptions&&t.descriptions.de)||"";};
 M.configLabel=function(cid,fallback){var t=CT[cid];var l=M.locale();
   return (t&&t[l])||fallback||cid;};
 /* UI gilt als vollstaendig, wenn jede Sprache jeden Schluessel hat. */
 M.uiComplete=function(l){var de=Object.keys(M.I18N.de||{});
   var t=M.I18N[l]||{};return de.every(function(k){return t[k]!==undefined;});};
 M.uiGaps=function(l){var t=M.I18N[l]||{};
   return Object.keys(M.I18N.de||{}).filter(function(k){return t[k]===undefined;});};
 })();

;

