function updateData(root){if(!root)return;
 (root.missingModules||[]).forEach(function(x){
   var id=x.id||x.moduleId,mod=MODULES.filter(function(m){return m.moduleId===id;})[0];
   if(mod){x.status=mod.residualRequirement?'FOUNDATION_IMPLEMENTED_RESIDUAL_REQUIREMENT':'IMPLEMENTED_PROVISIONAL';x.implementationChapterId=mod.chapterId;}
 });
 (root.authoringJobs||[]).forEach(function(x){
   var id=x.moduleId||x.id,mod=MODULES.filter(function(m){return m.moduleId===id;})[0];
   if(mod){x.status=mod.residualRequirement?'FOUNDATION_IMPLEMENTED_REVIEW_REQUIRED':'IMPLEMENTED_REVIEW_REQUIRED';x.implementationChapterId=mod.chapterId;}
 });
 (root.knownDefects||[]).forEach(function(x){if(DEFECT_STATUS[x.id])x.status=DEFECT_STATUS[x.id];});
}
